import * as React from "react"
import { Slot } from "@radix-ui/react-slot"
import { cva, type VariantProps } from "class-variance-authority"
import { PanelLeft } from "lucide-react"

import { useIsMobile } from "@/hooks/use-mobile"
import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Separator } from "@/components/ui/separator"
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet"
import { Skeleton } from "@/components/ui/skeleton"
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import {
  UIVariantProvider,
  useUIVariant,
  type UIVariant,
} from "@/components/ui/ui-variant-context"

const SIDEBAR_COOKIE_NAME = "sidebar_state"
const SIDEBAR_COOKIE_MAX_AGE = 60 * 60 * 24 * 7
const SIDEBAR_WIDTH = "16rem"
const SIDEBAR_WIDTH_MOBILE = "18rem"
const SIDEBAR_WIDTH_ICON = "3rem"
const SIDEBAR_KEYBOARD_SHORTCUT = "b"

type SidebarContextProps = {
  state: "expanded" | "collapsed"
  open: boolean
  setOpen: (open: boolean) => void
  openMobile: boolean
  setOpenMobile: (open: boolean) => void
  isMobile: boolean
  portalContainer: HTMLElement | null
  toggleSidebar: () => void
}

const SidebarContext = React.createContext<SidebarContextProps | null>(null)

function useSidebar() {
  const context = React.useContext(SidebarContext)
  if (!context) {
    throw new Error("useSidebar must be used within a SidebarProvider.")
  }

  return context
}

const SidebarProvider = React.forwardRef<
  HTMLDivElement,
  React.ComponentProps<"div"> & {
    defaultOpen?: boolean
    open?: boolean
    onOpenChange?: (open: boolean) => void
    /**
     * Breakpoint used for container-based mobile behavior.
     * In embedded contexts (docs sandboxes, modals), sidebar mobile mode is based on
     * this provider's rendered width instead of the top-level window width.
     */
    mobileBreakpoint?: number
    /**
     * `viewport` (default) — `min-h-svh` for full-page app shells.
     * `embedded` — `h-full min-h-0` to fill a parent (docs sandboxes, modals); avoids viewport-sized layout.
     */
    layout?: "viewport" | "embedded"
    sidebarWidth?: string
    sidebarWidthIcon?: string
  }
>(
  (
    {
      defaultOpen = true,
      open: openProp,
      onOpenChange: setOpenProp,
      mobileBreakpoint = 768,
      layout = "viewport",
      sidebarWidth = SIDEBAR_WIDTH,
      sidebarWidthIcon = SIDEBAR_WIDTH_ICON,
      className,
      style,
      children,
      ...props
    },
    ref
  ) => {
    const viewportIsMobile = useIsMobile()
    const wrapperRef = React.useRef<HTMLDivElement | null>(null)
    const [portalContainer, setPortalContainer] =
      React.useState<HTMLElement | null>(null)
    const [isContainerMobile, setIsContainerMobile] = React.useState<
      boolean | null
    >(null)
    const isMobile = isContainerMobile ?? viewportIsMobile
    const [openMobile, setOpenMobile] = React.useState(false)

    // This is the internal state of the sidebar.
    // We use openProp and setOpenProp for control from outside the component.
    const [_open, _setOpen] = React.useState(defaultOpen)
    const open = openProp ?? _open
    const setOpen = React.useCallback(
      (value: boolean | ((value: boolean) => boolean)) => {
        const openState = typeof value === "function" ? value(open) : value
        if (setOpenProp) {
          setOpenProp(openState)
        } else {
          _setOpen(openState)
        }

        // This sets the cookie to keep the sidebar state.
        document.cookie = `${SIDEBAR_COOKIE_NAME}=${openState}; path=/; max-age=${SIDEBAR_COOKIE_MAX_AGE}`
      },
      [setOpenProp, open]
    )

    // Helper to toggle the sidebar.
    const toggleSidebar = React.useCallback(() => {
      return isMobile
        ? setOpenMobile((open) => !open)
        : setOpen((open) => !open)
    }, [isMobile, setOpen, setOpenMobile])

    React.useEffect(() => {
      const node = wrapperRef.current
      if (!node) return
      setPortalContainer(node.ownerDocument?.body ?? null)

      const updateFromWidth = (width: number) => {
        setIsContainerMobile(width < mobileBreakpoint)
      }

      updateFromWidth(node.clientWidth)

      const view = node.ownerDocument?.defaultView
      const ResizeObserverCtor = view?.ResizeObserver ?? ResizeObserver
      if (!ResizeObserverCtor) return

      const observer = new ResizeObserverCtor((entries) => {
        const nextWidth = entries[0]?.contentRect.width
        if (typeof nextWidth === "number") {
          updateFromWidth(nextWidth)
        }
      })
      observer.observe(node)
      return () => observer.disconnect()
    }, [mobileBreakpoint])

    // Adds a keyboard shortcut to toggle the sidebar.
    React.useEffect(() => {
      const handleKeyDown = (event: KeyboardEvent) => {
        if (
          event.key === SIDEBAR_KEYBOARD_SHORTCUT &&
          (event.metaKey || event.ctrlKey)
        ) {
          event.preventDefault()
          toggleSidebar()
        }
      }

      window.addEventListener("keydown", handleKeyDown)
      return () => window.removeEventListener("keydown", handleKeyDown)
    }, [toggleSidebar])

    // We add a state so that we can do data-state="expanded" or "collapsed".
    // This makes it easier to style the sidebar with Tailwind classes.
    const state = open ? "expanded" : "collapsed"

    const contextValue = React.useMemo<SidebarContextProps>(
      () => ({
        state,
        open,
        setOpen,
        isMobile,
        openMobile,
        setOpenMobile,
        portalContainer,
        toggleSidebar,
      }),
      [
        state,
        open,
        setOpen,
        isMobile,
        openMobile,
        setOpenMobile,
        portalContainer,
        toggleSidebar,
      ]
    )

    return (
      <SidebarContext.Provider value={contextValue}>
        <TooltipProvider delayDuration={0}>
          <div
            style={
              {
                "--sidebar-width": sidebarWidth,
                "--sidebar-width-icon": sidebarWidthIcon,
                ...style,
              } as React.CSSProperties
            }
            className={cn(
              "group/sidebar-wrapper flex w-full items-stretch has-[[data-variant=inset]]:bg-sidebar",
              layout === "embedded" ? "h-full min-h-0" : "min-h-svh",
              className
            )}
            ref={(node) => {
              wrapperRef.current = node
              if (typeof ref === "function") {
                ref(node)
              } else if (ref) {
                ref.current = node
              }
            }}
            {...props}
          >
            {children}
          </div>
        </TooltipProvider>
      </SidebarContext.Provider>
    )
  }
)
SidebarProvider.displayName = "SidebarProvider"

const Sidebar = React.forwardRef<
  HTMLDivElement,
  React.ComponentProps<"div"> & {
    side?: "left" | "right"
    variant?: "sidebar" | "floating" | "inset"
    collapsible?: "offcanvas" | "icon" | "none"
    mode?: UIVariant
    /**
     * Where the desktop sidebar panel is positioned.
     * - `viewport` — `position: fixed` to the window (default shadcn behaviour; full-page apps).
     * - `contained` — `position: absolute` within the sidebar row; use in docs previews, modals, or any
     *   non–full-viewport shell so the rail and main content stay one layout unit.
     */
    sidebarPosition?: "viewport" | "contained"
  }
>(
  (
    {
      side = "left",
      variant = "sidebar",
      collapsible = "offcanvas",
      mode: modeProp,
      sidebarPosition = "viewport",
      className,
      children,
      ...props
    },
    ref
  ) => {
    const { isMobile, state, openMobile, setOpenMobile, portalContainer } =
      useSidebar()
    const mode = modeProp ?? useUIVariant()
    const isContained = sidebarPosition === "contained"
    const isPanelRounded = isContained || variant !== "sidebar"

    if (collapsible === "none") {
      return (
        <UIVariantProvider mode={mode}>
          <div
            className={cn(
              "flex h-full w-[var(--sidebar-width)] min-w-0 flex-col bg-sidebar text-sidebar-foreground",
              mode === "smooth" && isPanelRounded && "rounded-xl shadow-sm",
              mode === "playful" && isPanelRounded && "rounded-lg",
              className
            )}
            ref={ref}
            {...props}
          >
            {children}
          </div>
        </UIVariantProvider>
      )
    }

    if (isMobile) {
      return (
        <Sheet open={openMobile} onOpenChange={setOpenMobile} {...props}>
          <SheetContent
            container={portalContainer}
            data-sidebar="sidebar"
            data-mobile="true"
            className={cn(
              "w-[var(--sidebar-width)] bg-sidebar p-0 text-sidebar-foreground [&>button]:hidden",
              mode === "smooth" && "rounded-l-2xl",
              mode === "playful" && "rounded-l-lg"
            )}
            style={
              {
                "--sidebar-width": SIDEBAR_WIDTH_MOBILE,
              } as React.CSSProperties
            }
            side={side}
          >
            <SheetHeader className="sr-only">
              <SheetTitle>Sidebar</SheetTitle>
              <SheetDescription>Displays the mobile sidebar.</SheetDescription>
            </SheetHeader>
            <UIVariantProvider mode={mode}>
              <div className="flex h-full w-full min-w-0 flex-col">{children}</div>
            </UIVariantProvider>
          </SheetContent>
        </Sheet>
      )
    }

    const isCollapsed = state === "collapsed"
    const isIconCollapsed = isCollapsed && collapsible === "icon"
    const isOffcanvasCollapsed = isCollapsed && collapsible === "offcanvas"
    const panelWidthClass =
      variant === "floating" || variant === "inset"
        ? isIconCollapsed
          ? "w-[calc(var(--sidebar-width-icon)_+_theme(spacing.4)_+2px)]"
          : "w-[var(--sidebar-width)]"
        : isIconCollapsed
          ? "w-[var(--sidebar-width-icon)]"
          : "w-[var(--sidebar-width)]"

    return (
      <div
        ref={ref}
        className={cn(
          "group peer hidden min-w-0 shrink-0 text-sidebar-foreground md:block",
          isContained && "relative overflow-hidden transition-[width] duration-200 ease-linear",
          isContained && !isOffcanvasCollapsed && panelWidthClass,
          isContained && isOffcanvasCollapsed && "w-0"
        )}
        data-state={state}
        data-collapsible={state === "collapsed" ? collapsible : ""}
        data-variant={variant}
        data-side={side}
        data-sidebar-position={sidebarPosition}
        {...props}
      >
        {/* This is what handles the sidebar gap on desktop */}
        <div
          className={cn(
            "relative bg-transparent transition-[width] duration-200 ease-linear",
            isContained ? "hidden w-0 md:hidden" : "w-[var(--sidebar-width)]",
            "group-data-[side=right]:rotate-180",
            isOffcanvasCollapsed && "w-0",
            variant === "floating" || variant === "inset"
              ? isIconCollapsed
                ? "w-[calc(var(--sidebar-width-icon)_+_theme(spacing.4))]"
                : null
              : isIconCollapsed
                ? "w-[var(--sidebar-width-icon)]"
                : null
          )}
        />
        <div
          className={cn(
            isContained
              ? "relative z-10 hidden h-full min-w-0 shrink-0 overflow-hidden transition-[left,right,width] duration-200 ease-linear md:flex"
              : "fixed inset-y-0 z-10 hidden h-svh w-[var(--sidebar-width)] transition-[left,right,width] duration-200 ease-linear md:flex",
            side === "left"
              ? cn(
                  isContained ? "" : "left-0",
                  !isContained && isOffcanvasCollapsed && "left-[calc(var(--sidebar-width)*-1)]"
                )
              : cn(
                  isContained ? "" : "right-0",
                  !isContained && isOffcanvasCollapsed && "right-[calc(var(--sidebar-width)*-1)]"
                ),
            // Adjust the padding for floating and inset variants.
            variant === "floating" || variant === "inset"
              ? cn(
                  "p-2",
                  isContained && panelWidthClass,
                  !isContained && isIconCollapsed && "w-[calc(var(--sidebar-width-icon)_+_theme(spacing.4)_+2px)]"
                )
              : cn(
                  side === "left" ? "border-r" : "border-l",
                  isContained && panelWidthClass,
                  !isContained && isIconCollapsed && "w-[var(--sidebar-width-icon)]"
                ),
            className
          )}
        >
          <div
            data-sidebar="sidebar"
            className={cn(
              "flex h-full min-h-0 w-full min-w-0 flex-col bg-sidebar group-data-[variant=floating]:rounded-lg group-data-[variant=floating]:border group-data-[variant=floating]:border-sidebar-border group-data-[variant=floating]:shadow",
              mode === "smooth" && isPanelRounded && "rounded-xl shadow-sm",
              mode === "playful" && isPanelRounded && "rounded-lg"
            )}
          >
            <UIVariantProvider mode={mode}>{children}</UIVariantProvider>
          </div>
        </div>
      </div>
    )
  }
)
Sidebar.displayName = "Sidebar"

const SidebarTrigger = React.forwardRef<
  React.ElementRef<typeof Button>,
  React.ComponentProps<typeof Button>
>(({ className, onClick, ...props }, ref) => {
  const { toggleSidebar } = useSidebar()

  return (
    <Button
      ref={ref}
      data-sidebar="trigger"
      variant="ghost"
      size="icon"
      className={cn("h-7 w-7", className)}
      onClick={(event) => {
        onClick?.(event)
        toggleSidebar()
      }}
      {...props}
    >
      <PanelLeft />
      <span className="sr-only">Toggle Sidebar</span>
    </Button>
  )
})
SidebarTrigger.displayName = "SidebarTrigger"

const SidebarRail = React.forwardRef<
  HTMLButtonElement,
  React.ComponentProps<"button">
>(({ className, ...props }, ref) => {
  const { toggleSidebar } = useSidebar()

  return (
    <button
      ref={ref}
      data-sidebar="rail"
      aria-label="Toggle Sidebar"
      tabIndex={-1}
      onClick={toggleSidebar}
      title="Toggle Sidebar"
      className={cn(
        "absolute inset-y-0 z-20 hidden w-4 -translate-x-1/2 transition-all ease-linear after:absolute after:inset-y-0 after:left-1/2 after:w-[2px] hover:after:bg-sidebar-border group-data-[side=left]:-right-4 group-data-[side=right]:left-0 sm:flex",
        "[[data-side=left]_&]:cursor-w-resize [[data-side=right]_&]:cursor-e-resize",
        "[[data-side=left][data-state=collapsed]_&]:cursor-e-resize [[data-side=right][data-state=collapsed]_&]:cursor-w-resize",
        "group-data-[collapsible=offcanvas]:translate-x-0 group-data-[collapsible=offcanvas]:after:left-full group-data-[collapsible=offcanvas]:hover:bg-sidebar",
        "[[data-side=left][data-collapsible=offcanvas]_&]:-right-2",
        "[[data-side=right][data-collapsible=offcanvas]_&]:-left-2",
        className
      )}
      {...props}
    />
  )
})
SidebarRail.displayName = "SidebarRail"

const SidebarInset = React.forwardRef<
  HTMLDivElement,
  React.ComponentProps<"main">
>(({ className, ...props }, ref) => {
